def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the repeated full-width and full-height divider lines.
    div = next(grid[r][0] for r in range(h) if len(set(grid[r])) == 1)
    rows = [r for r in range(h) if all(v == div for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == div for r in range(h))]

    def segments(n, cuts):
        result, start = [], 0
        for cut in cuts + [n]:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        return result

    rg, cg = segments(h, rows), segments(w, cols)
    counts = {}
    for line in grid:
        for v in line:
            if v != div:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    mark = min(counts, key=counts.get)
    out = []
    for r0, r1 in rg:
        line = []
        for c0, c1 in cg:
            n = sum(grid[r][c] == mark for r in range(r0, r1) for c in range(c0, c1))
            line.append(background if n == 1 else 1)
        out.append(line)
    return out
